import React from "react";

export default function Certificate(opt) {
  const { description, img, date } = opt;
  return (
    <article class="certificate-item">
      <a href="assets/doc_react.pdf" target="_blank">
        <img src="${img}" alt="${description}" />
        <p class="certificate-desc">${description}</p>
        <p class="certificate-date">${date}</p>
      </a>
    </article>
  );
}
